            if not current_id:
                raise ScriptParseError(f"Line {line_number}: empty node id")
            if current_id in nodes_by_id:
                raise ScriptParseError(f"Line {line_number}: duplicate node id {current_id!r}")
            nodes_by_id[current_id] = _blank_node(current_id)
            ordered_node_ids.append(current_id)
            continue

        if current_id is None:
            raise ScriptParseError(f"Line {line_number}: content appears before the first [Node]")

        body, target = _split_edge(line, line_number)
        referenced_targets.add(target)
        node = nodes_by_id[current_id]

        choice = CHOICE_RE.match(body)
        if choice:
            if node["type"] == "line" and (node["text"] or node["speaker"]):
                raise ScriptParseError(f"Line {line_number}: node {current_id!r} mixes dialogue and choices")
            node["type"] = "choice"
            node["text"] = ""
            node["speaker"] = ""
            choice_text = f"{choice.group(1)}. {choice.group(2).strip()}"
            edges.append({"from": current_id, "to": target, "text": choice_text})
            continue

        dialogue = LINE_RE.match(body)
        if dialogue:
            if node["type"] == "choice" and any(edge["from"] == current_id for edge in edges):
                raise ScriptParseError(f"Line {line_number}: node {current_id!r} mixes choices and dialogue")
            speaker = dialogue.group(1).strip()
            dialogue_text = dialogue.group(2).strip()
            if not speaker:
                raise ScriptParseError(f"Line {line_number}: empty speaker")
            node["type"] = "line"
            node["speaker"] = speaker
            node["text"] = dialogue_text
            edges.append({"from": current_id, "to": target, "text": ""})
            continue

        raise ScriptParseError(f"Line {line_number}: could not parse line body: {body!r}")

    for target in sorted(referenced_targets - set(nodes_by_id)):
        nodes_by_id[target] = _blank_node(target)
        ordered_node_ids.append(target)

    graph = {
        "nodes": [nodes_by_id[node_id] for node_id in ordered_node_ids],
        "edges": edges,
    }
    _validate_graph(graph)
    return graph


def _dot_escape(value: str) -> str:
    return value.replace("\\", "\\\\").replace('"', r'\"').replace("\n", r"\n")


def graph_to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    lines = ["digraph Dialogue {", "  rankdir=LR;", "  node [fontname=\"Arial\"];"]
    for node in graph["nodes"]:
        if node["type"] == "choice":
            label = node["id"]
            shape = "diamond"
            fill = "lightblue"
        else:
            label = f"{node['id']}\\n{node['speaker']}: {node['text']}"
            shape = "box"
            fill = "lightyellow"
        lines.append(
            f'  "{_dot_escape(node["id"])}" [label="{_dot_escape(label)}", '
            f'shape={shape}, style="rounded,filled", fillcolor="{fill}"];'
        )

    for edge in graph["edges"]:
        attrs = []
        if edge["text"]:
            attrs.append(f'label="{_dot_escape(edge["text"])}"')
            if "[" in edge["text"] and "]" in edge["text"]:
                attrs.extend(['color="blue"', 'penwidth=2'])
            else:
                attrs.append('color="gray40"')
        attr_text = f" [{', '.join(attrs)}]" if attrs else ""
        lines.append(f'  "{_dot_escape(edge["from"])}" -> "{_dot_escape(edge["to"])}"{attr_text};')
    lines.append("}")
    return "\n".join(lines) + "\n"


def main() -> None:
    script_path = Path("/app/script.txt")
    json_path = Path("/app/dialogue.json")
    dot_path = Path("/app/dialogue.dot")

    graph = parse_script(script_path.read_text(encoding="utf-8"))
    json_path.write_text(json.dumps(graph, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    dot_path.write_text(graph_to_dot(graph), encoding="utf-8")


if __name__ == "__main__":
    main()
